import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func removeZeros(s string) string {
	return strings.ReplaceAll(s, "0", "")
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)

	scanner.Scan()
	aStr := scanner.Text()
	a, _ := strconv.Atoi(aStr)
	aMod, _ := strconv.Atoi(removeZeros(aStr))

	scanner.Scan()
	bStr := scanner.Text()
	b, _ := strconv.Atoi(bStr)
	bMod, _ := strconv.Atoi(removeZeros(bStr))

	c := a + b
	cMod, _ := strconv.Atoi(removeZeros(strconv.Itoa(c)))

	if aMod+bMod == cMod {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

